import { withTokenExpiry, ApiError } from "./authApi"; // shared ApiError class — see authApi.js comment

export const BASE = "https://api.aeo-app.com/api/v1";
// export const BASE = "http://localhost:8000/api/v1"; // for local dev

export const checkAuthTokens = () => {
  const idToken = localStorage.getItem("id_token");
  const accessToken = localStorage.getItem("access_token");
  const userId = localStorage.getItem("user_id");
  const token = [idToken, accessToken].find(candidate => candidate && !isTokenExpired(candidate));

  // If either token or user_id is missing, force login
  if (!token || !userId) {
    localStorage.removeItem("id_token");
    localStorage.removeItem("access_token");
    localStorage.removeItem("user_id");
    throw new ApiError("TokenExpired", "Your session has expired. Please sign in again.");
  }

  return { idToken: token, userId };
};

function isTokenExpired(token) {
  try {
    const payload = token.split('.')[1];
    const normalized = payload.replace(/-/g, '+').replace(/_/g, '/');
    const decoded = JSON.parse(atob(normalized));
    return typeof decoded.exp === 'number' && Date.now() >= decoded.exp * 1000;
  } catch {
    return false;
  }
}

// 🔹 Centralized Auth Headers
// Admin "act as customer": while set, every request carries X-Act-As-User and the
// server (which re-checks the caller is an admin) works on that customer's data.
let _actAs = "";
let _owner = null;        // which customer view set it, so a view that is closing can't switch off the one that just opened
let _origFetch = null;
export const getActAs = () => _actAs;
export const isActingAs = () => !!_actAs;
// While acting as a customer, every call to our API also carries the customer in the URL and is never served from the
// browser cache. That keeps one customer's answer from ever being reused for another, and still works if a gateway
// drops the custom X-Act-As-User header.
export const clearActAs = (owner) => { if (owner === undefined || owner === _owner) setActAs(""); };
export const setActAs = (userId, owner) => {
  _actAs = userId || "";
  _owner = _actAs ? (owner || null) : null;
  if (typeof window === "undefined") return;
  if (_actAs && !_origFetch) {
    _origFetch = window.fetch.bind(window);
    window.fetch = (input, init) => {
      const url = typeof input === "string" ? input : (input && input.url) || "";
      if (_actAs && url.startsWith(BASE) && !/[?&]act_as=/.test(url) && typeof input === "string") {
        return _origFetch(url + (url.includes("?") ? "&" : "?") + "act_as=" + encodeURIComponent(_actAs), { ...(init || {}), cache: "no-store" });
      }
      return _origFetch(input, init);
    };
  } else if (!_actAs && _origFetch) {
    window.fetch = _origFetch; _origFetch = null;
  }
};

export const getAuthHeaders = () => {
  const { idToken, userId } = checkAuthTokens(); // This will throw if tokens missing

  return {
    "Content-Type": "application/json",
    Authorization: `Bearer ${idToken}`, // Use id_token specifically
    "X-User-ID": userId, // Always include user_id
    ...(_actAs ? { "X-Act-As-User": _actAs } : {}),
  };
};

// 🔹 Generic POST helper with token expiry handling
async function post(path, body) {
  try {
    // Validate tokens before making request
    checkAuthTokens();

    const res = await fetch(`${BASE}${path}`, {
      method: "POST",
      headers: getAuthHeaders(),
      body: JSON.stringify(body),
    });

    const data = await res.json().catch(() => ({}));

    // Handle 401 Unauthorized (Token Expired)
    if (res.status === 401) {
      localStorage.removeItem("id_token");
      localStorage.removeItem("access_token");
      localStorage.removeItem("user_id");
      throw new ApiError("TokenExpired", "Your session has expired. Please sign in again.");
    }

    // 402 Payment Required — FastAPI's HTTPException(402, ...) returns just
    // {"detail": "..."}, no "code" field, so without this explicit check
    // every 402 would fall through to the generic "ServerError" branch below
    // and callers couldn't tell "you need to pay" apart from "something broke".
    if (res.status === 402) {
      throw new ApiError("PaymentRequired", data?.detail || "Payment required to access this feature.");
    }

    // 403 here specifically means the one-to-one user<->domain lock rejected
    // a different domain — distinct from a generic permissions error.
    if (res.status === 403) {
      throw new ApiError("DomainMismatch", data?.detail || "This account is linked to a different domain.");
    }

    if (!res.ok) {
      const errorCode = data?.code || data?.error_code || "ServerError";
      const errorMessage = data?.detail || data?.message || `Request failed (${res.status})`;
      throw new ApiError(errorCode, errorMessage);
    }

    return data;
  } catch (error) {
    // Re-throw as-is if already ApiError
    if (error instanceof ApiError) {
      throw error;
    }
    // Convert other errors
    throw new ApiError("ServerError", error.message || "Request failed");
  }
}

// 🔹 SEO APIs
export const seoApi = {
  competitors: (req) => post("/seo/competitors", req),
  keywords: (req) => post("/seo/keywords", req),
  profile: (req) => post("/seo/profile", req),
  domainAuthority: (req) => post("/seo/domain-authority", req),
  fullReport: (req) => post("/seo/full-report", req),
  contentStrategy: (req) => post("/seo/content-strategy", req),

  /**
   * Streams POST /seo/content-strategy/stream as Server-Sent Events.
   *
   * Native `EventSource` can't be used here — it only supports GET requests
   * with no custom headers/body, and this endpoint needs a POST body + an
   * Authorization header. Instead we read the fetch response body as a
   * stream and parse SSE frames ("event: x\ndata: y\n\n") by hand.
   *
   * @param {object} req - ContentStrategyRequest body
   * @param {(event: string, data: any) => void} onEvent - called per SSE event
   * @param {AbortSignal} [signal] - to cancel the stream (e.g. on unmount)
   */
  contentStrategyStream: async (req, onEvent, signal) => {
    checkAuthTokens();
    const res = await fetch(`${BASE}/seo/content-strategy/stream`, {
      method: "POST",
      headers: getAuthHeaders(),
      body: JSON.stringify(req),
      signal,
    });

    if (res.status === 401) {
      localStorage.removeItem("id_token");
      localStorage.removeItem("access_token");
      localStorage.removeItem("user_id");
      throw new ApiError("TokenExpired", "Your session has expired. Please sign in again.");
    }
    if (res.status === 402) {
      const data = await res.json().catch(() => ({}));
      throw new ApiError("PaymentRequired", data?.detail || "Payment required to access this feature.");
    }
    if (res.status === 403) {
      const data = await res.json().catch(() => ({}));
      throw new ApiError("DomainMismatch", data?.detail || "This account is linked to a different domain.");
    }
    if (!res.ok || !res.body) {
      const data = await res.json().catch(() => ({}));
      throw new ApiError(
        data?.code || "ServerError",
        data?.detail || data?.message || `Request failed (${res.status})`
      );
    }

    const reader = res.body.getReader();
    const decoder = new TextDecoder();
    let buffer = "";

    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      buffer += decoder.decode(value, { stream: true });

      // SSE frames are separated by a blank line ("\n\n")
      let sep;
      while ((sep = buffer.indexOf("\n\n")) !== -1) {
        const frame = buffer.slice(0, sep);
        buffer = buffer.slice(sep + 2);

        let eventName = "message";
        let dataLines = [];
        for (const line of frame.split("\n")) {
          if (line.startsWith("event:")) eventName = line.slice(6).trim();
          else if (line.startsWith("data:")) dataLines.push(line.slice(5).trim());
        }
        if (dataLines.length === 0) continue;

        let payload;
        try {
          payload = JSON.parse(dataLines.join("\n"));
        } catch {
          continue; // skip malformed frame rather than killing the whole stream
        }
        onEvent(eventName, payload);
      }
    }
  },
};